import { chromium } from 'playwright'
const BASE = process.env.PLAYWRIGHT_BASE_URL || 'http://127.0.0.1:8092'
const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1920, height: 953 } })
page.on('pageerror', e => console.log('[pageerror]', e.message))
page.on('console', m => { if(m.type()==='error') console.log('[console.err]', m.text()) })

// 直接进入二级页 projects
await page.goto(`${BASE}/index.html#/index?portal=projects`, { waitUntil: 'networkidle' })
for (const ms of [500, 1000, 2000, 4000]) {
  await page.waitForTimeout(ms === 500 ? 500 : (ms - (ms===1000?500:ms===2000?1000:2000)))
  const info = await page.evaluate(() => {
    const sk = document.querySelector('.portal-skeleton')
    const tableLoading = document.querySelectorAll('.portal-table-loading-line').length
    const rows = document.querySelectorAll('.portal-table tbody tr, .el-table__row').length
    return { hash: location.hash, skVisible: sk?getComputedStyle(sk).display:'none', tableLoading, rows }
  })
  console.log(`@t=${ms}ms`, JSON.stringify(info))
}
await page.screenshot({ path: 'tests/e2e/portal-projects.png' })
await browser.close()

