import { chromium } from 'playwright'
const BASE = 'http://127.0.0.1:8081'
const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1920, height: 953 } })
page.on('pageerror', e => console.log('[pageerror]', e.message))
page.on('console', m => { if(m.type()==='error') console.log('[console.err]', m.text().slice(0,160)) })

await page.goto(`${BASE}/`, { waitUntil: 'networkidle', timeout: 60000 })
await page.waitForTimeout(2500)

// DOM-click 可售楼盘
await page.evaluate(() => {
  const el = Array.from(document.querySelectorAll('*')).find(n => n.textContent.trim() === '可售楼盘' && n.children.length === 0)
  el && el.click()
})
await page.waitForTimeout(400)
console.log('hash after click:', await page.evaluate(() => location.hash))

for (const t of [500, 1000, 2000, 4000]) {
  await page.waitForTimeout(t === 500 ? 500 : t - (t === 1000 ? 500 : t === 2000 ? 1000 : 2000))
  const info = await page.evaluate(() => {
    const sk = document.querySelector('.portal-skeleton')
    const lines = document.querySelectorAll('.portal-table-loading-line').length
    const rows = document.querySelectorAll('.el-table__row, .portal-table tbody tr').length
    return { hash: location.hash, sk: sk ? getComputedStyle(sk).display + '/' + (sk.offsetParent?'vis':'no') : 'none', lines, rows }
  })
  console.log(`@${t}ms`, JSON.stringify(info))
}
await page.screenshot({ path: 'tests/e2e/dev-8081-sub.png' })
await browser.close()

